cypress_script:
describe('Web Tables CRUD Operations', () => {
  beforeEach(() => {
    cy.visit('https://demoqa.com/webtables');
  });

  it('should add a new record successfully', () => {
    cy.get('#addNewRecordButton').click();
    // Assuming fields to enter new record are present and filled here.
    cy.get('input').first().type('John');
    cy.get('input').eq(1).type('Doe');
    cy.get('input').eq(2).type('john.doe@example.com');
    cy.get('input').eq(3).type('30');
    cy.get('input').eq(4).type('Engineer');
    cy.get('button').contains('Submit').click();
    cy.url().should('eq', 'https://demoqa.com/webtables');
    cy.get('#searchBox').type('John');
    cy.get('div').contains('John Doe').should('be.visible');
  });

  it('should not add a record with empty fields', () => {
    cy.get('#addNewRecordButton').click();
    cy.get('button').contains('Submit').click();
    cy.url().should('eq', 'https://demoqa.com/webtables');
    cy.get('div').should('not.exist');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Web Tables CRUD Operations', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://demoqa.com/webtables');
  });

  test('should add a new record successfully', async ({ page }) => {
    await page.click('#addNewRecordButton');
    // Assuming fields to enter new record are present and filled here.
    await page.fill('input', 'John');
    await page.fill('input', 'Doe');
    await page.fill('input', 'john.doe@example.com');
    await page.fill('input', '30');
    await page.fill('input', 'Engineer');
    await page.click('button:has-text("Submit")');
    await expect(page).toHaveURL('https://demoqa.com/webtables');
    await page.fill('#searchBox', 'John');
    await expect(page.locator('div').withText('John Doe')).toBeVisible();
  });

  test('should not add a record with empty fields', async ({ page }) => {
    await page.click('#addNewRecordButton');
    await page.click('button:has-text("Submit")');
    await expect(page).toHaveURL('https://demoqa.com/webtables');
    await expect(page.locator('div')).not.toBeVisible();
  });
});
